# Lightweight IoT Security Processor custom-ISA demo
#
# The current testbench uses raw machine encodings generated by enc_custom().
# In a normal assembler flow, these can be emitted with .word until assembler
# aliases are added.
#
# custom-0 opcode = 0x0B
# funct3 commands:
#   0: CSEC_XOR
#   1: CSEC_AES_STATUS
#   2: CSEC_AES_START
#   3: CSEC_AES_CT0
#   4: CSEC_AES_CLEAR

    .section .text
    .globl _start

_start:
    addi x1, x0, 15       # plaintext low word
    addi x2, x0, 51       # plaintext next word

    # CSEC_XOR x3, x1, x2
    .word 0x0020818b

    # CSEC_AES_STATUS x4
    .word 0x0000120b

    # CSEC_AES_START x5, x1, x2
    .word 0x0020a28b

poll_aes:
    # CSEC_AES_STATUS x6
    .word 0x0000130b
    andi x7, x6, 2
    beq  x7, x0, poll_aes

    # CSEC_AES_CT0 x8
    .word 0x0000340b

    # CSEC_AES_CLEAR x9
    .word 0x0000448b

done:
    jal x0, done
